function solve(l1, l2) {
  const toBig = (d) => BigInt([...d].reverse().join('') || '0');
  const sum = (toBig(l1) + toBig(l2)).toString().split('').reverse().map(Number);
  return sum;
}

function solve(l1, l2) {
  const out = [];
  let carry = 0, i = 0;
  while (i < l1.length || i < l2.length || carry) {
    const s = (l1[i] || 0) + (l2[i] || 0) + carry;
    carry = Math.floor(s / 10);
    out.push(s % 10);
    i++;
  }
  return out;
}

